WITH cleaned AS (SELECT id, full_name, email, job_title, salary, hire_date, is_remote, level, TRIM(full_name) AS clean_full_name, COALESCE(level, 'OTHER') AS level_clean FROM employees WHERE job_title IS NOT NULL AND YEAR(hire_date) >= 2023), scored AS (SELECT id, full_name, email, job_title, salary, hire_date, SUM(salary) OVER (PARTITION BY level, job_title ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_salary, LAST_VALUE(job_title, TRUE) OVER (PARTITION BY level ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_job_title FROM cleaned), cleaned_employees AS (SELECT *, CAST(cumulative_salary AS DOUBLE) AS cumulative_salary_str, COALESCE(job_title, 'N/A') AS job_title_filled FROM scored WHERE hire_date > TO_DATE('2023-05-04') AND email IS NULL), ranked AS (SELECT *, RANK() OVER (PARTITION BY job_title ORDER BY salary DESC) AS rank_in_group FROM cleaned_employees QUALIFY rank_in_group = 1), report AS (SELECT id, email, salary, hire_date, cumulative_salary, last_known_job_title, cumulative_salary_str, rank_in_group FROM ranked ORDER BY cumulative_salary_str DESC NULLS FIRST) SELECT id, hire_date, cumulative_salary, last_known_job_title, cumulative_salary_str FROM report ORDER BY hire_date DESC;
